export type LearnedMarketsPluginPdas = {
  config: typeof findConfigPda;
  board: typeof findBoardPda;
  walletBinding: typeof findWalletBindingPda;
  market: typeof findMarketPda;
  baseVault: typeof findBaseVaultPda;
  quoteVault: typeof findQuoteVaultPda;
  sourceBinding: typeof findSourceBindingPda;
  position: typeof findPositionPda;
  newWalletBinding: typeof findNewWalletBindingPda;
};

export type LearnedMarketsPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function learnedMarketsProgram(
  config: { programAddress?: Address | HasAddress } = {},
) {
  return <T extends LearnedMarketsPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { learnedMarkets: LearnedMarketsPlugin }> => {
    return extendClient(client, {
      learnedMarkets: {
        accounts: {
          boardConfig: addSelfFetchFunctions(client, getBoardConfigCodec()),
          config: addSelfFetchFunctions(client, getConfigCodec()),
          intent: addSelfFetchFunctions(client, getIntentCodec()),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          participant: addSelfFetchFunctions(client, getParticipantCodec()),
          position: addSelfFetchFunctions(client, getPositionCodec()),
          walletBinding: addSelfFetchFunctions(client, getWalletBindingCodec()),
        },
        instructions: {
          cancelIntent: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelIntentInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createMarket: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMarketInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          depositBase: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositBaseInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          depositQuote: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositQuoteInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          initializeBoard: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeBoardInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          initializeConfig: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConfigInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          registerParticipant: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterParticipantInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          replaceBinding: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getReplaceBindingInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                {
                  programAddress:
                    instructionConfig?.programAddress ?? config.programAddress,
                },
              ),
            ),
          revokeParticipant: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeParticipantInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          setStage: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetStageInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          settleBatch: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleBatchInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          submitIntent: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSubmitIntentInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          suspendParticipant: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSuspendParticipantInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          updateBoard: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateBoardInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          updateConfig: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateConfigInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdrawBase: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawBaseInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          withdrawQuote: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawQuoteInstructionAsync(input, {
                programAddress:
                  instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
        },
        pdas: {
          config: (pdaConfig) =>
            findConfigPda({
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          board: (pdaConfig) =>
            findBoardPda({
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          walletBinding: (seeds, pdaConfig) =>
            findWalletBindingPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          market: (seeds, pdaConfig) =>
            findMarketPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          baseVault: (seeds, pdaConfig) =>
            findBaseVaultPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          quoteVault: (seeds, pdaConfig) =>
            findQuoteVaultPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          sourceBinding: (seeds, pdaConfig) =>
            findSourceBindingPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          position: (seeds, pdaConfig) =>
            findPositionPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
          newWalletBinding: (seeds, pdaConfig) =>
            findNewWalletBindingPda(seeds, {
              programAddress:
                pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyLearnedMarketsAccount,
        identifyInstruction: identifyLearnedMarketsInstruction,
        parseInstruction: parseLearnedMarketsInstruction,
      } as LearnedMarketsPlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
